import csv,collections
rows=list(csv.DictReader(open('responses.csv')))
P={2,4,8,16,32,64}
d=collections.defaultdict(lambda:[0,0])
for r in rows:
  ex=[int(x) for x in r['number_set'].split(',')]
  if all(e in P for e in ex):
    t=int(r['target'])
    if t in ex: k='ex'
    elif t in P: k='pow2'
    elif t%2==0: k='even'
    else: k='odd'
    d[(r['number_set'],k)][0]+=int(r['rating']); d[(r['number_set'],k)][1]+=1
for k in sorted(d): print(k, d[k], round(d[k][0]/d[k][1],2))
